def compute(vars):
    revenue_2019 = vars["v1"]
    revenue_2018 = vars["v2"]
    change = revenue_2019 - revenue_2018

    return {
        "value": change,
        "trace": {
            "revenue_2019": revenue_2019,
            "revenue_2018": revenue_2018,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "thousands",
                "unit": "currency"
            }
        }
    }
